def count_Primes_nums(n):
    """
    Function to count the number of prime numbers less than a given non-negative number n.
    """
    if n <= 2:
        return 0  # No prime numbers exist less than 2

    # Step 1: Create a boolean array for prime numbers
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not primes

    # Step 2: Use Sieve of Eratosthenes to identify primes
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            # Mark multiples of i starting from i*i as not prime
            for multiple in range(i * i, n, i):
                is_prime[multiple] = False

    # Step 3: Count and return the number of primes
    return sum(is_prime)
