def max_sub_array_sum_repeated(arr, n, k):
    # Helper function: Kadane's algorithm for maximum subarray sum in a single array
    def kadane(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # Compute basic properties
    total_sum = sum(arr)
    prefix_max = float('-inf')
    suffix_max = float('-inf')
    current_prefix_sum = 0
    current_suffix_sum = 0

    # Compute prefix sums
    for i in range(n):
        current_prefix_sum += arr[i]
        prefix_max = max(prefix_max, current_prefix_sum)

    # Compute suffix sums
    for i in range(n - 1, -1, -1):
        current_suffix_sum += arr[i]
        suffix_max = max(suffix_max, current_suffix_sum)

    # Kadane's max for one array
    kadane_max = kadane(arr)

    # Combine results based on the value of k
    if k == 1:
        return kadane_max
    elif k == 2:
        return max(kadane_max, prefix_max + suffix_max)
    else:
        if total_sum > 0:
            return max(kadane_max, prefix_max + suffix_max + (k - 2) * total_sum)
        else:
            return max(kadane_max, prefix_max + suffix_max)

# Example tests for verification
