assert max_sub_array_sum_repeated([-5, -2, -8], 3, 2) == -2
assert max_sub_array_sum_repeated([1, 2], 2, 3) == 9
assert max_sub_array_sum_repeated([1, -1, 2, -2, 3], 5, 4) == 12
assert max_sub_array_sum_repeated([1, -2, 3, 4], 4, 5) == 20
