def start_withp(word_list):
    # Initialize an empty list to store words starting with 'p' or 'P'
    result = []

    # Iterate through each string in the list
    for phrase in word_list:
        # Split the string into individual words
        words = phrase.split()
        # Check each word
        for word in words:
            # If the word starts with 'p' or 'P', add it to the result
            if word.lower().startswith('p'):
                result.append(word)
                # If we already have two words, return the result
                if len(result) == 2:
                    return tuple(result)

    # If we found fewer than 2 words, pad with None or return appropriately
    return tuple(result) if len(result) == 2 else tuple(result + [None] * (2 - len(result)))
