def find_kth(arr1, arr2, k):
    """Find the k-th element in the union of two sorted arrays."""
    def kth_helper(a, b, k):
        # Base cases
        if not a:  # If the first array is empty
            return b[k - 1]
        if not b:  # If the second array is empty
            return a[k - 1]
        if k == 1:  # If k is 1, return the minimum of the first elements
            return min(a[0], b[0])

        # Determine the index to compare in each array
        idx_a = min(len(a), k // 2) - 1
        idx_b = min(len(b), k // 2) - 1

        # Compare elements at the chosen indices
        if a[idx_a] <= b[idx_b]:
            # Exclude the first idx_a + 1 elements of array a
            return kth_helper(a[idx_a + 1:], b, k - (idx_a + 1))
        else:
            # Exclude the first idx_b + 1 elements of array b
            return kth_helper(a, b[idx_b + 1:], k - (idx_b + 1))

    # Input validation
    if not (1 <= k <= len(arr1) + len(arr2)):
        raise ValueError("k is out of bounds for the combined length of the arrays.")

    return kth_helper(arr1, arr2, k)

# Example usage
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
