def tuple_to_dict(input_tuple):
    """
    Convert a tuple into a dictionary using adjacent elements as key-value pairs.

    :param input_tuple: Tuple containing elements to be converted
    :return: Dictionary with adjacent elements as key-value pairs
    """
    # Ensure the tuple has an even number of elements
    if len(input_tuple) % 2 != 0:
        input_tuple = input_tuple[:-1]

    # Create the dictionary by iterating through the tuple in steps of 2
    result_dict = {input_tuple[i]: input_tuple[i + 1] for i in range(0, len(input_tuple), 2)}

    return result_dict

# Tests
